import os, re
root=os.path.expanduser('~/.hermes')
patterns=[re.compile(r'route_store\.py.*append'), re.compile(r'is_synthetic'), re.compile(r'--synthetic'), re.compile(r'RouteStore\(')]
for dirpath, _, filenames in os.walk(root):
    for fn in filenames:
        if not fn.endswith(('.py','.sh','.md','.json','.yaml','.yml','.txt')):
            continue
        path=os.path.join(dirpath, fn)
        try:
            with open(path, 'r', errors='ignore') as f:
                for i,line in enumerate(f,1):
                    if any(p.search(line) for p in patterns):
                        if 'backups/' in path or '/hermes-agent/' in path:
                            continue
                        print(f'{path}:{i}:{line.rstrip()}')
        except Exception:
            pass
